      ]
    },
    {
      "name": "LoginLogMapper.insertLog",
      "relative_path": "src/main/java/com/example/shop/mapper/LoginLogMapper.java",
      "detail": "在用户不存在、账号停用、密码错误和登录成功四个分支写入对应登录原因。",
      "kind": "direct",
      "source_ids": [
        "sr1:2ed8ee8d",
