      ]
    },
    {
      "name": "SessionService.createSession",
      "relative_path": "src/main/java/com/example/shop/session/SessionService.java",
      "detail": "登录成功后生成 UUID，并写入 Redis 会话。",
      "kind": "direct",
      "source_ids": [
        "sr1:2ed8ee8d",
        "sr1:18ff860d"
      ]
    },
    {
      "name": "AuthFailedException",
      "relative_path": "src/main/java/com/example/shop/exception/AuthFailedException.java",
      "detail": "用于用户不存在、账号停用和密码错误分支；异常类的具体处理器未在本次范围内读取。",
      "kind": "direct",
      "source_ids": [
        "sr1:2ed8ee8d"
      ]
    }
  ],
  "data_accesses": [
    {
      "object": "app_user",
      "category": "db_object",
      "operations": [
        "read"
      ],
      "conditions": [
        "每次登录首先按 username 查询"
      ],
      "access_method": "SELECT id, username, password_hash, status FROM app_user WHERE username = #{username}",
      "state": {
