      "conditions": [
        "仅登录成功后创建会话"
      ],
      "access_method": "redis.opsForValue().set(\"session:\" + sessionId, String.valueOf(userId), Duration.ofHours(2))",
      "state": {
        "type": "observed"
      },
      "source_ids": [
        "sr1:18ff860d",
        "sr1:2ed8ee8d"
      ]
    }
  ],
